#!/usr/bin/env bash
# Linux rootless Podman, no Compose or application runtime required on the host.
set -euo pipefail
umask 077
cd -- "$(dirname -- "${BASH_SOURCE[0]}")"
fail() { echo "Erreur : $*" >&2; exit 1; }
command -v podman >/dev/null || fail 'Podman est requis.'
[[ -f release.env ]] || fail 'release.env absent : utiliser le paquet de livraison.'
# Generated by package-podman.sh; contains shell-quoted image references, no secrets.
source release.env
APP_IMAGE=${APP_IMAGE:-$RELEASE_APP_IMAGE}
DB_IMAGE=$RELEASE_DB_IMAGE
command=${1:-help}
if [[ $command == init ]]; then
    [[ ! -e instance.env && ! -e secrets ]] || fail 'Installation déjà initialisée ; conserver ses secrets.'
    INSTANCE_NAME=${INSTANCE_NAME:-pole-formation}
    [[ $INSTANCE_NAME =~ ^[a-z][a-z0-9-]{0,40}$ ]] || fail 'INSTANCE_NAME invalide.'
    mkdir -m 700 secrets backups
    for key in postgres-password spring.datasource.password deployment.admin.password; do
        od -An -N24 -tx1 /dev/urandom | tr -d ' \n' > "secrets/$key"
        printf '\n' >> "secrets/$key"
    done
    printf 'INSTANCE_NAME=%q\nBIND_ADDRESS=127.0.0.1\nHTTP_PORT=%q\nCOOKIE_SECURE=false\nADMIN_USERNAME=admin\n' "$INSTANCE_NAME" "${HTTP_PORT:-8080}" > instance.env
    echo 'Installation initialisée. Mot de passe admin : secrets/deployment.admin.password'
    exit 0
fi
[[ -f instance.env ]] || fail 'Exécuter d’abord : bash deploy.sh init'
source instance.env
[[ $INSTANCE_NAME =~ ^[a-z][a-z0-9-]{0,40}$ ]] || fail 'INSTANCE_NAME invalide.'
[[ $HTTP_PORT =~ ^[0-9]+$ && $HTTP_PORT -gt 0 && $HTTP_PORT -le 65535 ]] || fail 'HTTP_PORT invalide.'
[[ $COOKIE_SECURE == true || $COOKIE_SECURE == false ]] || fail 'COOKIE_SECURE invalide.'
[[ $BIND_ADDRESS == 127.0.0.1 || $COOKIE_SECURE == true ]] || fail 'Hors boucle locale, HTTPS et COOKIE_SECURE=true sont requis.'
app=$INSTANCE_NAME-app
db=$INSTANCE_NAME-db
network=$INSTANCE_NAME-net
volume=$INSTANCE_NAME-pgdata
wait_database() {
    for ((attempt=0; attempt<60; attempt++)); do
        if podman exec "$db" pg_isready -h 127.0.0.1 -U postgres -d pole_formation >/dev/null 2>&1; then return; fi
        [[ $(podman inspect -f '{{.State.Running}}' "$db") == true ]] || fail "PostgreSQL arrêté : podman logs $db"
        sleep 1
    done
    fail "PostgreSQL indisponible : podman logs $db"
}
up() {
    podman image exists "$APP_IMAGE" || fail 'Image application absente : bash deploy.sh load'
    podman image exists "$DB_IMAGE" || fail 'Image PostgreSQL absente : bash deploy.sh load'
    for key in postgres-password spring.datasource.password deployment.admin.password; do
        [[ -s secrets/$key ]] || fail "Secret manquant : secrets/$key"
        if ! podman secret exists "$INSTANCE_NAME-$key"; then
            podman secret create "$INSTANCE_NAME-$key" "secrets/$key" >/dev/null
        fi
    done
    podman network exists "$network" || podman network create "$network" >/dev/null
    podman volume exists "$volume" || podman volume create "$volume" >/dev/null
    if ! podman container exists "$db"; then
        podman run -d --name "$db" --network "$network" --network-alias database \
            --restart unless-stopped --pull never \
            --secret "$INSTANCE_NAME-postgres-password,target=postgres-password" \
            --secret "$INSTANCE_NAME-spring.datasource.password,target=app-db-password" \
            -e POSTGRES_PASSWORD_FILE=/run/secrets/postgres-password -e POSTGRES_DB=pole_formation \
            -v "$volume:/var/lib/postgresql" \
            -v "$PWD/init-database.sh:/docker-entrypoint-initdb.d/10-app.sh:ro,Z" "$DB_IMAGE" >/dev/null
    else
        podman start "$db" >/dev/null
    fi
    wait_database
    if ! podman container exists "$app"; then
        podman run -d --name "$app" --network "$network" --restart unless-stopped --pull never \
            --cap-drop ALL --security-opt no-new-privileges \
            -p "$BIND_ADDRESS:$HTTP_PORT:8080" \
            --secret "$INSTANCE_NAME-spring.datasource.password,target=spring.datasource.password,uid=1001,gid=0,mode=0400" \
            --secret "$INSTANCE_NAME-deployment.admin.password,target=deployment.admin.password,uid=1001,gid=0,mode=0400" \
            -e SPRING_PROFILES_ACTIVE=standalone -e SPRING_CONFIG_IMPORT=configtree:/run/secrets/ \
            -e SPRING_DATASOURCE_URL=jdbc:postgresql://database:5432/pole_formation \
            -e SPRING_DATASOURCE_USERNAME=pole_formation -e DEPLOYMENT_ADMIN_USERNAME="$ADMIN_USERNAME" \
            -e SERVER_SERVLET_SESSION_COOKIE_SECURE="$COOKIE_SECURE" "$APP_IMAGE" >/dev/null
    else
        [[ $(podman inspect -f '{{.ImageName}}' "$app") == "$APP_IMAGE" ]] || fail 'Autre image en cours : utiliser update après sauvegarde.'
        podman start "$app" >/dev/null
    fi
    # Application health is checked inside the image; does not require curl on the host.
    for ((attempt=0; attempt<90; attempt++)); do
        if podman healthcheck run "$app" >/dev/null 2>&1; then
            echo "Application disponible sur $BIND_ADDRESS:$HTTP_PORT (image $APP_IMAGE)"; return
        fi
        [[ $(podman inspect -f '{{.State.Running}}' "$app") == true ]] || fail "Application arrêtée : podman logs $app"
        sleep 2
    done
    fail "Application indisponible : podman logs $app"
}
backup() {
    mkdir -p backups
    local destination="backups/$(date -u +%Y%m%dT%H%M%S)-$$.dump"
    if podman exec "$db" pg_dump -U postgres -d pole_formation -Fc > "$destination.partial"; then
        mv -- "$destination.partial" "$destination"
        echo "Sauvegarde : $destination"
    else
        fail "Sauvegarde échouée (fichier incomplet : $destination.partial)."
    fi
}
case "$command" in
    load)
        (cd -- "${2:-.}"; sha256sum -c SHA256SUMS)
        podman load -i "${2:-.}/application.tar"
        podman load -i "${2:-.}/postgres.tar"
        ;;
    up) up ;;
    stop)
        for container in "$app" "$db"; do
            if podman container exists "$container"; then podman stop -t 30 "$container" >/dev/null; fi
        done
        ;;
    status)
        podman ps -a --filter "name=^${INSTANCE_NAME}-(app|db)$"
        ;;
    logs) podman logs --tail 100 -f "$app" ;;
    backup) backup ;;
    restore)
        [[ ${3:-} == --replace-data && -f ${2:-} ]] || fail 'Usage : restore sauvegarde.dump --replace-data (écrase la base ; application arrêtée).'
        if podman container exists "$app"; then
            [[ $(podman inspect -f '{{.State.Running}}' "$app") == false ]] || fail 'Arrêter l’application avant restauration.'
        fi
        wait_database
        podman exec -i "$db" pg_restore -U postgres -d pole_formation --clean --if-exists --exit-on-error --single-transaction < "$2"
        ;;
    update)
        podman image exists "$APP_IMAGE" || fail 'Charger la nouvelle image avant update.'
        backup
        if podman container exists "$app"; then
            podman stop -t 30 "$app" >/dev/null
            podman rm "$app" >/dev/null
        fi
        up
        ;;
    *) echo 'Usage : bash deploy.sh init|load [paquet]|up|stop|status|logs|backup|restore fichier --replace-data|update' ;;
esac
